<?php
declare(strict_types=1);
$root=getenv('RUNNER_TEMP');
require $root.'/local/bootstrap.php';
$local=sokna_local_bootstrap(require $root.'/config.php');
$p=$local->database();
$a=function($ok,$m){if(!$ok)throw new RuntimeException($m);};
$admin=$p->prepare("INSERT INTO users(username,password_hash,display_name,role,active) VALUES(?,?,?,'admin',1)");
$admin->execute(['qa-admin-i',password_hash('FixtureOnly-Admin-2026',PASSWORD_DEFAULT),'QA admin']);$actor=['id'=>(int)$p->lastInsertId()];
$svc=$local->adminControls();
$u=['username'=>'qa-only-i','display_name'=>'QA staff','active'=>true,'capabilities'=>['orders_floor'],'password'=>'1234'];
$id=(int)$svc->saveUser($u,$actor)['id'];
$staff=['id'=>$id];$u['id']=$id;
$project=function()use($local,$id){return array_values(array_filter($local->publicProjectionBuilder()->authProjections(),fn($r)=>$r['projection_id']==='user:'.$id));};
$a($project()===[],'Local-only PIN must not project to Public');
$lookup=function()use($svc,$actor,$id){foreach($svc->snapshot($actor)['users'] as $row)if((int)$row['id']===$id)return $row;throw new RuntimeException('missing user');};
$a($lookup()['remote_login_ready']===0,'false remote readiness');
$u['capabilities'][]='remote_access';$u['password']='';
$reject=function($fn)use($a){try{$fn();throw new LogicException('unsafe access transition accepted');}catch(\Sokna\Local\Domain\Admin\AdminControlException $e){$a($e->errorCode==='remote_password_required','wrong rejection '.$e->errorCode);}};
$reject(fn()=>$svc->saveUser($u,$actor));
$team=['user_id'=>$id,'display_name'=>'QA staff','active'=>true,'system_access'=>true,'username'=>$u['username'],'password'=>'','capabilities'=>$u['capabilities'],'preparation_areas'=>[]];
$reject(fn()=>$svc->saveTeamMember($team,$actor));
$a($project()===[],'denied transition changed projection');
$u['password']='FixtureOnly-Remote-One';
$svc->saveUser($u,$actor);
$a(count($project())===1,'missing remote user');$a($lookup()['remote_login_ready']===1,'remote readiness missing');
foreach(['Core/Config','Core/Database','Core/Migrations','Auth/AuthProjectionService','Auth/AuthThrottle','Auth/AuthSecurityAudit','Auth/PublicSessionStore','Auth/PublicLoginService'] as $f)require $root.'/public/src/'.$f.'.php';
$p->exec('CREATE DATABASE sokna_ci_public_i CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');
$cfg=\Sokna\PublicEdge\Core\Config::fromArray(['db'=>['host'=>'127.0.0.1','port'=>'3306','name'=>'sokna_ci_public_i','user'=>'root','pass'=>getenv('SOKNA_CI_DB_PASS')]]);
$q=\Sokna\PublicEdge\Core\Database::connect($cfg);
$m=new \Sokna\PublicEdge\Core\Migrations($q,$root.'/public/database/migrations');
$projection=new \Sokna\PublicEdge\Auth\AuthProjectionService($q);
$sessions=new \Sokna\PublicEdge\Auth\PublicSessionStore($q);
$loginService=new \Sokna\PublicEdge\Auth\PublicLoginService($q,new \Sokna\PublicEdge\Auth\AuthThrottle($q),$sessions,new \Sokna\PublicEdge\Auth\AuthSecurityAudit($q));
$a(count($m->migrate())===11,'Public schema migrations');
$q->prepare("INSERT INTO installations(installation_id,display_name) VALUES(?,?)")->execute(['qa-only-i','QA only']);
$sync=function()use($projection,$local){return $projection->sync('qa-only-i',$local->publicProjectionBuilder()->authProjections());};
$login=function($password)use($loginService,$u){return $loginService->login('qa-only-i',$u['username'],$password,'qa-test');};
$sync();$l=$login($u['password']);$a($l['ok']===true,'initial remote login');
$token=$l['token'];$sync();$a($sessions->resolve($token)!==null,'unchanged sync revoked session');
$next='FixtureOnly-Remote-Two';$local->account()->changePassword(['current_password'=>$u['password'],'new_password'=>$next,'confirm_password'=>$next],$staff);
$a($sessions->resolve($token)!==null,'test expected disconnected old projection until sync');
$sync();$a($sessions->resolve($token)===null,'old session survived password change');
$a($login($u['password'])['ok']===false,'old password still works after sync');
$l=$login($next);$a($l['ok']===true,'new password rejected');
$u['password']='';$u['capabilities']=['cashier_accounts','remote_access'];$svc->saveUser($u,$actor);
$sync();$a($sessions->resolve($l['token'])===null,'role change not revoked');
$l=$login($next);$a(in_array('finance.settle',$l['capabilities'],true)&&!in_array('orders.mutate',$l['capabilities'],true),'capabilities not authoritative');
$u['capabilities']=['cashier_accounts'];$svc->saveUser($u,$actor);$sync();
$a($sessions->resolve($l['token'])===null,'remote removal did not revoke');$a($login($next)['ok']===false,'remote removal still allows login');
$a($lookup()['remote_login_ready']===0,'remote disabled falsely ready');
$u['capabilities'][]='remote_access';$reject(fn()=>$svc->saveUser($u,$actor));
$team['password']='FixtureOnly-Remote-Three';$savedTeam=$svc->saveTeamMember($team,$actor);$team['personnel_id']=$savedTeam['personnel_id'];$sync();
$l=$login($team['password']);$a($l['ok']===true,'team activation failed');
$team['password']='';$team['system_access']=false;$svc->saveTeamMember($team,$actor);$sync();
$a($sessions->resolve($l['token'])===null,'deactivated account still valid');$a($login($team['password']===''?'FixtureOnly-Remote-Three':$team['password'])['ok']===false,'deactivated login accepted');
echo json_encode(['status'=>'PASS','two_real_databases'=>true,'pin_only_local'=>true,'both_access_transitions_guarded'=>true,'identical_sync_preserves_session'=>true,'password_change_revokes_session'=>true,'capability_change_revokes_session'=>true,'remote_removal_revokes_session'=>true,'team_reactivation_and_deactivation'=>true,'disconnected_public_state_retained_until_authoritative_sync'=>true],JSON_THROW_ON_ERROR)."\n";

$oldId='user:'.$id;
$u['username']='qa-renamed-old';$u['password']='';$u['active']=false;$u['capabilities']=['orders_floor'];
$svc->saveUser($u,$actor);
$new=['username'=>'qa-only-i','display_name'=>'QA replacement','active'=>true,'capabilities'=>['cashier_accounts','remote_access'],'password'=>'FixtureOnly-New-Identity'];
$new['id']=(int)$svc->saveUser($new,$actor)['id'];$newId='user:'.$new['id'];
$sync();
$n=$loginService->login('qa-only-i',$new['username'],$new['password'],'qa-new');$a($n['ok']===true&&$n['projection_id']===$newId,'reused name points to wrong identity');
$a($sessions->resolve($n['token'])!==null,'new session');
$read=function()use($q){return $q->query("SELECT projection_id,username,active,capabilities_json FROM auth_projections WHERE installation_id='qa-only-i' ORDER BY projection_id")->fetchAll(PDO::FETCH_ASSOC);};
$state=$read();$byId=array_column($state,null,'projection_id');
$a((int)$byId[$oldId]['active']===0&&(int)$byId[$newId]['active']===1,'old identity not retired');
$canonical=$local->publicProjectionBuilder()->authProjections();
$bad=$canonical[0];$bad['projection_id']='user:99999999';$bad['username']=strtoupper($new['username']);
try{$projection->sync('qa-only-i',[...$canonical,$bad]);throw new LogicException('duplicate username accepted');}catch(PDOException $e){$a((int)($e->errorInfo[1]??0)===1062,'unexpected SQL rejection');}
$a($read()===$state&&$sessions->resolve($n['token'])!==null,'invalid set changed authoritative rows/session');
try{$projection->sync('qa-only-i',[...$canonical,$canonical[0]]);throw new LogicException('duplicate projection accepted');}catch(RuntimeException $e){$a($e->getMessage()==='invalid_projection_identity','unexpected identity rejection');}
try{$projection->sync('qa-only-i',[['projection_id'=>'user:bad']]);throw new LogicException('malformed identity accepted');}catch(RuntimeException $e){$a($e->getMessage()==='invalid_projection_identity','malformed rejection');}
$a($read()===$state&&$sessions->resolve($n['token'])!==null,'invalid set mutated live session');
$u['password']='FixtureOnly-Old-Reactivation';$u['active']=true;$u['capabilities']=['orders_floor','remote_access'];$svc->saveUser($u,$actor);$sync();
$o=$loginService->login('qa-only-i',$u['username'],$u['password'],'qa-old');$a($o['ok']===true&&$o['projection_id']===$oldId,'old identity reactivation');
$a($sessions->resolve($n['token'])!==null,'unrelated session revoked');
$origOld=$u['username'];$origNew=$new['username'];
$u['username']='qa-swap-intermediate';$u['password']='';$svc->saveUser($u,$actor);
$new['username']=$origOld;$new['password']='';$svc->saveUser($new,$actor);
$u['username']=$origNew;$svc->saveUser($u,$actor);
$sync();
$a($sessions->resolve($o['token'])===null&&$sessions->resolve($n['token'])===null,'swapped username sessions not revoked');
$x=$loginService->login('qa-only-i',$origNew,'FixtureOnly-Old-Reactivation','qa-swap');$y=$loginService->login('qa-only-i',$origOld,'FixtureOnly-New-Identity','qa-swap');
$a($x['ok']&&$x['projection_id']===$oldId&&$y['ok']&&$y['projection_id']===$newId,'swap identity mapping');
echo json_encode(['status'=>'PASS','retired_username_reuse'=>true,'old_identity_preserved'=>true,'duplicate_username_atomic_rejection'=>true,'duplicate_id_rejected'=>true,'malformed_set_rejected'=>true,'reactivation'=>true,'username_swap'=>true,'unrelated_session_preserved'=>true,'changed_sessions_revoked'=>true],JSON_THROW_ON_ERROR)."\n";
